package com.puppyquest;

import net.runelite.api.coords.WorldPoint;

/**
 * Approximate centres of the nine wandering-dog search regions.
 * These are GUIDE MARKERS, not the NPC's live position; each dog wanders.
 * Keep coordinates editable for map refinements in future releases.
 */
public enum PuppyQuestBreed
{
    BERNESE("Bernese Mountain Dog", "Bernese Mountain Dog puppy", "Timber", "bernese", 2721, 3698,
        "East of Rellekka, by the Keldagrim entrance and Rock Crabs", "Rellekka", 2668, 3685),
    COLLIE("Border Collie", "Border Collie puppy", "Victor", "collie", 2927, 3295,
        "Crafting Guild / Dark Wizards' Tower / Makeover Mage", "Rimmington", 2958, 3221),
    CHIHUAHUA("Chihuahua", "Chihuahua puppy", "Leo", "chihuahua", 3471, 3004,
        "Uzer Oasis: buildings, hill and dungeon entrance", "Shantay Pass", 3305, 3121),
    CORGI("Corgi", "Corgi puppy", "Loot", "corgi", 2673, 3310,
        "East Ardougne: Aemad's shop, nearby bank and zoo", "East Ardougne", 2665, 3304),
    GREYHOUND("Greyhound", "Greyhound puppy", "Wrigley", "greyhound", 1668, 3423,
        "South of Woodcutting Guild, west of Crabclaw Caves", "Hosidius", 1735, 3521),
    HUSKY("Husky", "Husky puppy", "Zoey", "husky", 1685, 3962,
        "Fishing Hamlet, east of Wintertodt", "Wintertodt Camp", 1632, 3943),
    SAMOYED("Samoyed", "Samoyed puppy", "Artsi", "samoyed", 2793, 3109,
        "Northern Tai Bwo Wannai / Hardwood Grove", "Tai Bwo Wannai", 2797, 3085),
    SHIBA("Shiba", "Shiba puppy", "Keanna", "shiba", 1655, 3020,
        "Avium Savannah: around the pyre fox hunting area", "Civitas illa Fortis (south gate)", 1666, 3140),
    YORKIE("Yorkie", "Yorkie puppy", "Smoky", "yorkie", 3163, 2462,
        "The Great Conch: west of the Summer Shore marketplace", "Great Conch marketplace", 3184, 2500);

    private final String displayName;
    private final String itemName;
    private final String dogNpcName;
    private final String configKey;
    private final WorldPoint point;
    private final String searchArea;
    private final String suggestedTown;
    private final WorldPoint suggestedTownPoint;

    PuppyQuestBreed(String displayName, String itemName, String dogNpcName, String configKey,
        int x, int y, String searchArea, String suggestedTown, int townX, int townY)
    {
        this.displayName = displayName;
        this.itemName = itemName;
        this.dogNpcName = dogNpcName;
        this.configKey = configKey;
        this.point = new WorldPoint(x, y, 0);
        this.searchArea = searchArea;
        this.suggestedTown = suggestedTown;
        this.suggestedTownPoint = new WorldPoint(townX, townY, 0);
    }

    public String getDisplayName() { return displayName; }
    public String getItemName() { return itemName; }
    public String getDogNpcName() { return dogNpcName; }
    public String getConfigKey() { return configKey; }
    public WorldPoint getPoint() { return point; }
    public String getSearchArea() { return searchArea; }
    public String getSuggestedTown() { return suggestedTown; }
    public WorldPoint getSuggestedTownPoint() { return suggestedTownPoint; }
}

