package com.puppyquest;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Highlights a dog ONLY after its NPC enters the player's loaded game area. */
public class PuppyQuestOverlay extends Overlay
{
    private static final Color CYAN = new Color(30, 234, 244, 238);
    private static final Color DARK = new Color(18, 22, 27, 220);
    private final Client client;
    private final PuppyQuestPlugin plugin;
    private final PuppyQuestConfig config;

    @Inject
    public PuppyQuestOverlay(Client client, PuppyQuestPlugin plugin, PuppyQuestConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.highlightNearbyDogs() || client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        for (NPC npc : client.getNpcs())
        {
            PuppyQuestBreed breed = plugin.findBreedByNpc(npc.getName());
            if (breed == null)
            {
                continue;
            }
            Shape hull = npc.getConvexHull();
            if (hull == null)
            {
                hull = npc.getCanvasTilePoly();
            }
            if (hull == null)
            {
                continue;
            }
            graphics.setColor(new Color(30, 234, 244, 40));
            graphics.fill(hull);
            graphics.setStroke(new BasicStroke(2.5f));
            graphics.setColor(CYAN);
            graphics.draw(hull);

            Rectangle bounds = hull.getBounds();
            if (bounds.width <= 0 || bounds.height <= 0)
            {
                continue;
            }
            // High-contrast box and a down-facing arrow above the actual NPC.
            graphics.setStroke(new BasicStroke(2.2f));
            graphics.drawRoundRect(bounds.x - 4, bounds.y - 4,
                bounds.width + 8, bounds.height + 8, 9, 9);
            int centreX = bounds.x + bounds.width / 2;
            int pointY = bounds.y - 7;
            Polygon arrow = new Polygon(
                new int[]{centreX - 9, centreX + 9, centreX},
                new int[]{pointY - 17, pointY - 17, pointY}, 3);
            graphics.setColor(DARK);
            graphics.fillPolygon(arrow);
            graphics.setColor(CYAN);
            graphics.setStroke(new BasicStroke(2f));
            graphics.drawPolygon(arrow);
            graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
            String label = breed.getDisplayName();
            int textX = centreX - graphics.getFontMetrics().stringWidth(label) / 2;
            int textY = pointY - 22;
            graphics.setColor(DARK);
            graphics.drawString(label, textX + 1, textY + 1);
            graphics.setColor(Color.WHITE);
            graphics.drawString(label, textX, textY);
        }
        return null;
    }
}

package com.puppyquest;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/** Dedicated RuneLite sidebar: 9 breeds, collection state and approximate GPS. */
public class PuppyQuestPanel extends PluginPanel
{
    private static final Color TEXT = new Color(226, 226, 226);
    private static final Color MUTED = new Color(166, 166, 166);
    private final PuppyQuestPlugin plugin;
    private final JPanel rows = new JPanel();
    private final JLabel progress = new JLabel();
    private final JLabel guidance = new JLabel();
    private final Map<PuppyQuestBreed, JCheckBox> checks = new EnumMap<>(PuppyQuestBreed.class);
    private final Map<PuppyQuestBreed, JButton> guideButtons = new EnumMap<>(PuppyQuestBreed.class);

    PuppyQuestPanel(PuppyQuestPlugin plugin)
    {
        this.plugin = plugin;
        setLayout(new BorderLayout(0, 9));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(12, 10, 10, 10));

        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(getBackground());
        JLabel title = new JLabel("Puppy Quest");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 17f));
        title.setForeground(TEXT);
        header.add(title);
        JLabel by = new JLabel("by KeirSkunk");
        by.setForeground(MUTED);
        header.add(by);
        header.add(Box.createVerticalStrut(9));
        progress.setForeground(TEXT);
        header.add(progress);
        header.add(Box.createVerticalStrut(7));
        guidance.setForeground(MUTED);
        guidance.setText("<html>Select Guide beside a breed to mark its search area.<br>Nearest-town pins are hints, not routes.</html>");
        header.add(guidance);
        add(header, BorderLayout.NORTH);

        rows.setBackground(getBackground());
        rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
        for (PuppyQuestBreed breed : PuppyQuestBreed.values())
        {
            JPanel row = new JPanel(new BorderLayout(5, 2));
            row.setMaximumSize(new Dimension(245, 52));
            row.setBorder(BorderFactory.createEmptyBorder(4, 2, 4, 2));
            row.setBackground(getBackground());
            JCheckBox found = new JCheckBox(breed.getDisplayName());
            found.setOpaque(false);
            found.setForeground(TEXT);
            found.addActionListener(e -> plugin.setRescued(breed, found.isSelected()));
            checks.put(breed, found);
            row.add(found, BorderLayout.CENTER);
            JButton guide = new JButton("Guide");
            guide.addActionListener(e -> plugin.track(breed));
            guideButtons.put(breed, guide);
            row.add(guide, BorderLayout.EAST);
            rows.add(row);
        }
        add(rows, BorderLayout.CENTER);

        JPanel footer = new JPanel(new BorderLayout(0, 7));
        footer.setBackground(getBackground());
        JButton clear = new JButton("Clear navigation");
        clear.addActionListener(e -> plugin.clearTracking());
        footer.add(clear, BorderLayout.NORTH);
        JLabel note = new JLabel("<html>Dog outlines appear only when the NPC is nearby.<br>Ticked breeds remain on the world map.</html>");
        note.setForeground(MUTED);
        footer.add(note, BorderLayout.CENTER);
        add(footer, BorderLayout.SOUTH);
        refresh();
    }

    void refresh()
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(this::refresh);
            return;
        }
        int count = 0;
        for (PuppyQuestBreed breed : PuppyQuestBreed.values())
        {
            boolean rescued = plugin.isRescued(breed);
            if (rescued)
            {
                count++;
            }
            checks.get(breed).setSelected(rescued);
            JButton button = guideButtons.get(breed);
            button.setText(plugin.getTrackedBreed() == breed ? "Tracking" : "Guide");
        }
        progress.setText(count + " / 9 wandering breeds rescued");
        PuppyQuestBreed selected = plugin.getTrackedBreed();
        if (selected != null)
        {
            if (plugin.isTrackedNpcVisible())
            {
                guidance.setText("<html><b>Tracking " + selected.getDisplayName() + "</b><br>"
                    + "LIVE DOG DETECTED!<br>Arrow + map pin follow the dog<br>while it is nearby.</html>");
            }
            else
            {
                guidance.setText("<html><b>Tracking " + selected.getDisplayName() + "</b><br>Suggested start: "
                    + selected.getSuggestedTown() + "<br>Searching approximate area.<br>Arrow switches to dog when nearby.</html>");
            }
        }
        else
        {
            guidance.setText("<html>Click Guide next to a breed.<br>Shows its approximate location and starting town.</html>");
        }
        revalidate();
        repaint();
    }
}

package com.puppyquest;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.BasicStroke;
import java.awt.Polygon;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.Map;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/** World-map dog-search pins using the ACTUAL puppy inventory item sprites. */
@PluginDescriptor(
    name = "Puppy Quest",
    description = "By KeirSkunk - find all nine rescue dogs from A Ruff Situation on the OSRS world map",
    tags = {"puppy", "dog", "quest", "map", "a ruff situation"}
)
public class PuppyQuestPlugin extends Plugin
{
    // This short interval contains the 2026 puppy-item additions. Scanned on login
    // so colour variants can be found without hardcoding fragile item IDs.
    private static final int FIRST_PUPPY_ITEM_ID = 34500;
    private static final int LAST_PUPPY_ITEM_ID = 34699;

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ItemManager itemManager;
    @Inject private WorldMapPointManager worldMapPointManager;
    @Inject private PuppyQuestConfig config;
    @Inject private ConfigManager configManager;
    @Inject private ClientToolbar clientToolbar;
    @Inject private OverlayManager overlayManager;
    @Inject private PuppyQuestOverlay nearbyDogOverlay;

    private PuppyQuestPanel sidebar;
    private NavigationButton navigationButton;
    private volatile PuppyQuestBreed trackedBreed;
    private boolean ownsHintArrow;
    private WorldPoint ownedHintTarget;
    private NPC ownedHintNpc;
    private volatile boolean trackedNpcVisible;

    private final List<WorldMapPoint> markers = new ArrayList<>();
    private final Map<PuppyQuestBreed, WorldMapPoint> breedMarkers =
        new EnumMap<>(PuppyQuestBreed.class);

    @Provides
    PuppyQuestConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(PuppyQuestConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(nearbyDogOverlay);
        // RuneLite's actual item sprite for the black Labrador puppy is used
        // for the sidebar tab. We keep an offline fallback for the login screen.
        clientThread.invokeLater(() ->
        {
            BufferedImage icon = loadBlackLabradorIcon();
            SwingUtilities.invokeLater(() ->
            {
                sidebar = new PuppyQuestPanel(this);
                navigationButton = NavigationButton.builder()
                    .tooltip("Puppy Quest - by KeirSkunk")
                    .priority(7)
                    .icon(icon)
                    .panel(sidebar)
                    .build();
                clientToolbar.addNavigation(navigationButton);
            });
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                refreshMarkers();
            }
        });
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(nearbyDogOverlay);
        clearHintArrowIfOurs();
        trackedBreed = null;
        trackedNpcVisible = false;
        removeMarkers();
        NavigationButton button = navigationButton;
        if (button != null)
        {
            SwingUtilities.invokeLater(() -> clientToolbar.removeNavigation(button));
        }
        navigationButton = null;
        sidebar = null;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invokeLater(() ->
            {
                refreshMarkers();
                // The client may reset hint arrows on a hop or login.
                // Re-establish guidance only when the user selected a breed.
                if (trackedBreed != null && !client.hasHintArrow())
                {
                    pointAtSearchArea(trackedBreed);
                }
                updateTrackedDog();
            });
        }
        else
        {
            ownsHintArrow = false;
            ownedHintTarget = null;
            ownedHintNpc = null;
            trackedNpcVisible = false;
        }
    }

    /**
     * RuneLite only knows an NPC's exact location while it is loaded nearby.
     * During that window point directly at the moving NPC, not the static
     * centre of its search region; otherwise use the approximate location.
     */
    @Subscribe
    public void onGameTick(GameTick event)
    {
        updateTrackedDog();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if ("puppyquest".equals(event.getGroup()))
        {
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                clientThread.invokeLater(this::refreshMarkers);
            }
            refreshSidebar();
        }
    }

    /**
     * Best-effort rescue tracking. RuneLite receives the clicked NPC action but
     * there is currently no verified, documented dog-unlock varbit in this
     * prototype. The user can manually untick any false positive.
     *
     * This does NOT import breeds rescued before the plugin was installed.
     */
    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!config.autoTrackRescues() || !"rescue".equals(normalize(event.getMenuOption())))
        {
            return;
        }

        String target = normalize(event.getMenuTarget().replaceAll("<[^>]*>", ""));
        for (PuppyQuestBreed breed : PuppyQuestBreed.values())
        {
            if (target.equals(normalize(breed.getDisplayName()))
                || target.equals(normalize(breed.getDogNpcName())))
            {
                configManager.setConfiguration("puppyquest", breed.getConfigKey(), true);
                return;
            }
        }
    }

    private void refreshMarkers()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        removeMarkers();
        for (PuppyQuestBreed breed : PuppyQuestBreed.values())
        {
            boolean rescued = isRescued(breed);
            int itemId = locatePuppyItemId(breed.getItemName());
            BufferedImage image = itemId >= 0 ? itemManager.getImage(itemId) : makeFallbackIcon();
            if (image == null)
            {
                image = makeFallbackIcon();
            }

            // Always display every breed. Overlay the same puppy sprite with a
            // red X (not rescued) or green tick (rescued), quest-marker style.
            BufferedImage statusImage = PuppyQuestStatusIcon.withStatus(image, rescued);
            WorldMapPoint marker = WorldMapPoint.builder()
                .worldPoint(breed.getPoint())
                .image(statusImage)
                .name(breed.getDisplayName())
                // WorldMapPoint tooltips are plain text: RuneLite's <col> and
                // <br> tags appeared literally in the previous prototype.
                .tooltip(breed.getDisplayName() + (rescued ? " [RESCUED] - " : " [NOT RESCUED] - ")
                    + breed.getSearchArea() + " (approximate; dog wanders)")
                .jumpOnClick(true)
                .build();

            worldMapPointManager.add(marker);
            markers.add(marker);
            breedMarkers.put(breed, marker);
        }
        if (trackedBreed != null && config.showTownStart())
        {
            WorldMapPoint startingPoint = WorldMapPoint.builder()
                .worldPoint(trackedBreed.getSuggestedTownPoint())
                .image(makeStartIcon())
                .name("Puppy Quest suggested start")
                .tooltip("Suggested starting point: " + trackedBreed.getSuggestedTown()
                    + " - NOT a calculated walking path")
                .jumpOnClick(true)
                .build();
            worldMapPointManager.add(startingPoint);
            markers.add(startingPoint);
        }
        updateTrackedDog();
        refreshSidebar();
    }

    /** Locate untradeable puppy items in the local game cache, not GE-price search. */
    private int locatePuppyItemId(String targetName)
    {
        String wanted = normalize(targetName);
        for (int id = FIRST_PUPPY_ITEM_ID; id <= LAST_PUPPY_ITEM_ID; id++)
        {
            ItemComposition item = itemManager.getItemComposition(id);
            if (item != null && normalize(item.getName()).equals(wanted)
                && item.getNote() == -1 && item.getPlaceholderTemplateId() == -1)
            {
                return id;
            }
        }
        return -1;
    }

    private static String normalize(String s)
    {
        return s == null ? "" : s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
    }

    boolean isRescued(PuppyQuestBreed breed)
    {
        switch (breed)
        {
            case BERNESE: return config.bernese();
            case COLLIE: return config.collie();
            case CHIHUAHUA: return config.chihuahua();
            case CORGI: return config.corgi();
            case GREYHOUND: return config.greyhound();
            case HUSKY: return config.husky();
            case SAMOYED: return config.samoyed();
            case SHIBA: return config.shiba();
            case YORKIE: return config.yorkie();
            default: return false;
        }
    }

    // The 3 quest-unlocked starter breeds are not in the nine wandering dogs.
    // The black Labrador item sprite belongs to that starter breed.
    private BufferedImage loadBlackLabradorIcon()
    {
        int candidate = -1;
        int matches = 0;
        for (int id = FIRST_PUPPY_ITEM_ID; id <= LAST_PUPPY_ITEM_ID; id++)
        {
            ItemComposition item = itemManager.getItemComposition(id);
            if (item != null && normalize(item.getName()).equals("labradorpuppy")
                && item.getNote() == -1 && item.getPlaceholderTemplateId() == -1)
            {
                if (candidate < 0) candidate = id;
                // Labrador puppy has golden, chocolate and black colour variants;
                // the third matching cache item is used for the black variant.
                matches++;
                if (matches == 3)
                {
                    candidate = id;
                    break;
                }
            }
        }
        if (candidate >= 0)
        {
            BufferedImage itemIcon = itemManager.getImage(candidate);
            if (itemIcon != null)
            {
                BufferedImage icon = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
