    PuppyQuestBreed findBreedByNpc(String npcName)
    {
        String target = normalize(npcName);
        if (target.isEmpty()) return null;
        for (PuppyQuestBreed breed : PuppyQuestBreed.values())
        {
            if (target.equals(normalize(breed.getDogNpcName()))
                || target.equals(normalize(breed.getDisplayName())))
            {
                return breed;
            }
        }
        return null;
    }

    PuppyQuestBreed getTrackedBreed() { return trackedBreed; }
    boolean isTrackedNpcVisible() { return trackedNpcVisible; }

    void setRescued(PuppyQuestBreed breed, boolean rescued)
    {
        configManager.setConfiguration("puppyquest", breed.getConfigKey(), rescued);
        refreshSidebar();
    }

    void track(PuppyQuestBreed breed)
    {
        // All game client calls happen on RuneLite's client thread.
        clientThread.invokeLater(() ->
        {
            clearHintArrowIfOurs();
            trackedBreed = breed;
            trackedNpcVisible = false;
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                pointAtSearchArea(breed);
                refreshMarkers();
                updateTrackedDog();
            }
            refreshSidebar();
        });
    }

    void clearTracking()
    {
        clientThread.invokeLater(() ->
        {
            clearHintArrowIfOurs();
            trackedBreed = null;
            trackedNpcVisible = false;
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                refreshMarkers();
            }
            refreshSidebar();
        });
    }

    private void pointAtSearchArea(PuppyQuestBreed breed)
    {
        client.setHintArrow(breed.getPoint());
        ownedHintTarget = breed.getPoint();
        ownedHintNpc = null;
        ownsHintArrow = true;
    }

    private void pointAtActualDog(NPC dog)
    {
        client.setHintArrow(dog);
        ownedHintNpc = dog;
        ownedHintTarget = null;
        ownsHintArrow = true;
    }

    /**
     * Check that an arrow is still ours before clearing or changing it.
     * Quest Helper or a game event may have installed another arrow instead.
     */
    private boolean isOurHintArrow()
    {
        if (!ownsHintArrow)
        {
            return false;
        }
        if (ownedHintNpc != null)
        {
            return client.getHintArrowNpc() == ownedHintNpc;
        }
        return ownedHintTarget != null
            && ownedHintTarget.equals(client.getHintArrowPoint());
    }

    private void updateTrackedDog()
    {
        PuppyQuestBreed breed = trackedBreed;
        if (breed == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        NPC found = null;
        for (NPC npc : client.getNpcs())
        {
            if (breed == findBreedByNpc(npc.getName()))
            {
                found = npc;
                break;
            }
        }
        boolean live = found != null;

        // Move the tracked dog's existing world-map pin to its current tile.
        // Other breeds continue to display their fixed search-region pins.
        WorldMapPoint marker = breedMarkers.get(breed);
        if (marker != null)
        {
            WorldPoint destination = live ? found.getWorldLocation() : breed.getPoint();
            if (destination != null && !destination.equals(marker.getWorldPoint()))
            {
                marker.setWorldPoint(destination);
            }
            String rescueStatus = isRescued(breed) ? "RESCUED" : "NOT RESCUED";
            String detail = live ? "LIVE DOG LOCATION - moves with NPC"
                : "SEARCH AREA - approximate; dog wanders";
            String tooltip = breed.getDisplayName() + " [" + rescueStatus + "] - " + detail;
            if (!tooltip.equals(marker.getTooltip()))
            {
                marker.setTooltip(tooltip);
            }
        }

        // Respect another plugin if it took over our hint arrow. If our dog
        // despawned and RuneLite cleared the NPC arrow, resume the search pin.
        if (ownsHintArrow)
        {
            if (!isOurHintArrow() && client.hasHintArrow()
                && (client.getHintArrowNpc() != null
                    || client.getHintArrowPoint() != null
                    || client.getHintArrowPlayer() != null))
            {
                // Another plugin or game quest changed the arrow. Leave it alone.
                ownsHintArrow = false;
                ownedHintNpc = null;
                ownedHintTarget = null;
            }
            else if (live)
            {
                if (client.getHintArrowNpc() != found)
                {
                    pointAtActualDog(found);
                }
            }
            else if (!breed.getPoint().equals(client.getHintArrowPoint()))
            {
                pointAtSearchArea(breed);
            }
        }
        if (trackedNpcVisible != live)
        {
            trackedNpcVisible = live;
            refreshSidebar();
        }
    }

    private void clearHintArrowIfOurs()
    {
        if (isOurHintArrow())
        {
            client.clearHintArrow();
        }
        ownsHintArrow = false;
        ownedHintTarget = null;
        ownedHintNpc = null;
    }

    private void refreshSidebar()
    {
        PuppyQuestPanel panel = sidebar;
        if (panel != null)
        {
            panel.refresh();
        }
    }

    private void removeMarkers()
    {
        for (WorldMapPoint marker : markers)
        {
            worldMapPointManager.remove(marker);
        }
        markers.clear();
        breedMarkers.clear();
    }

    private static BufferedImage makeFallbackIcon()
    {
        BufferedImage icon = new BufferedImage(30, 30, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(74, 46, 22));
        g.fillOval(1, 1, 28, 28);
        g.setColor(new Color(252, 205, 99));
        g.fillOval(3, 3, 24, 24);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 19));
        g.setColor(Color.BLACK);
        g.drawString("?", 10, 22);
        g.dispose();
        return icon;
    }
