package com.puppyquest;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Adds a quest-style status badge to the ORIGINAL puppy item sprite.
 * Works with regular RuneLite item images and our fallback question-mark icon.
 */
final class PuppyQuestStatusIcon
{
    private static final Color RESCUED_GREEN = new Color(28, 153, 65);
    private static final Color MISSING_RED = new Color(201, 45, 45);
    private static final int BADGE_SIZE = 16;

    private PuppyQuestStatusIcon() { }

    static BufferedImage withStatus(BufferedImage sprite, boolean rescued)
    {
        // Extra space on the right/bottom lets the whole dog face remain visible.
        final int width = Math.max(36, sprite.getWidth()) + 8;
        final int height = Math.max(32, sprite.getHeight()) + 6;
        BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = result.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.drawImage(sprite, 0, 0, null);

            final int badgeX = width - BADGE_SIZE - 1;
            final int badgeY = height - BADGE_SIZE - 1;

            // Dark outline provides contrast against all world-map terrain.
            g.setColor(new Color(25, 25, 25, 230));
            g.fillOval(badgeX - 1, badgeY - 1, BADGE_SIZE + 2, BADGE_SIZE + 2);
            g.setColor(rescued ? RESCUED_GREEN : MISSING_RED);
            g.fillOval(badgeX + 1, badgeY + 1, BADGE_SIZE - 2, BADGE_SIZE - 2);
            g.setColor(Color.WHITE);
            g.setStroke(new BasicStroke(2.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

            if (rescued)
            {
                // Check mark: visible even if the user cannot distinguish red/green.
                g.drawLine(badgeX + 4, badgeY + 8, badgeX + 7, badgeY + 11);
                g.drawLine(badgeX + 7, badgeY + 11, badgeX + 12, badgeY + 5);
            }
            else
            {
                // X mark: not yet found.
                g.drawLine(badgeX + 5, badgeY + 5, badgeX + 11, badgeY + 11);
                g.drawLine(badgeX + 11, badgeY + 5, badgeX + 5, badgeY + 11);
            }
        }
        finally
        {
            g.dispose();
        }
        return result;
    }
}

